apps/simulators/src/ems/model.ts.source:
/**
 * The EMS simulator (Phase 6 slice 6b, builder B; EMS contract; DI-31, DI-32, DI-49; D-P6b-6): room temperature and
 * relative humidity sensors of the Tablets rooms, published on the feed as native series chunks, with the room alarms
 * the EMS raises (limit excursions the client posts, and the EMS's own FEED_GAP occurrence when a sensor stops).
 *
 *   POST /ems/v1/samples     {roomCode, tag, samples: [{raw, status?}, ...]}   one ems.series_chunk
 *   POST /ems/v1/alarms      {roomCode, occurrenceId, transition, alarmCode, severity, tag?, value?, limit?, limitKind?, message}
 *   POST /ems/v1/sensor-gap  {roomCode, tag, on}   the sensor stops reporting (on: its samples are refused and the EMS
 *                            raises FEED_GAP for the room) or reports again (off: the occurrence is cleared)
 *
 * The rooms are the ones the client reports for (the eBMR decides whether it knows the room). Chunk numbers count up
 * from 1 per room and tag; each sample gets its own strictly increasing source time (the server time equals it); the
 * value shown is the canonical decimal the raw text states exactly (DI-32), none for a BAD status. SIMULATOR, DEMO-ONLY.
 */
import {
  canonicalDecimal,
  EMS,
  EMS_TAGS,
  qualityOfStatus,
  RawNumberText,
  seriesChunkHash,
  StatusCodeText,
  type NativeSample,
  type SeriesChunkV1,
} from '@ebmr/integration-sdk/adapter';
import { SystemFeed, systemClock, type FeedClock } from '../system-feed/feed.ts';
import { contractPlugin } from '../system-feed/plugin.ts';
import type { FeedPlugin } from '../system-feed/server.ts';

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const unitOf = (tag: unknown): string | undefined => EMS_TAGS.find((t) => t.tag === tag)?.unit;

/** One native sample from what a sensor reported: the shown value is the raw text's exact decimal, none when BAD. */
export function nativeSample(raw: string, status: string, sourceTime: bigint): NativeSample {
  const good = StatusCodeText.safeParse(status).success && qualityOfStatus(status) !== 'BAD';
  const value = good && RawNumberText.safeParse(raw).success ? canonicalDecimal(raw) : null;
  return { sourceTime: sourceTime.toString(), serverTime: sourceTime.toString(), raw, value, status };
}

/** The chunk with its hash recomputed (after a change of its subject, WRONG_BATCH). */
function rehashed(p: Record<string, unknown>): Record<string, unknown> {
  return { ...p, chunkHash: seriesChunkHash(p as unknown as SeriesChunkV1) };
}

export interface EmsModel {
  /** The last chunk number published per `room/tag`. */
  chunkNo: Map<string, number>;
  /** The sensors (`room/tag`) that stopped reporting, with their open FEED_GAP occurrence. */
  silent: Map<string, string>;
}

export function emsSimulator(clock?: FeedClock): { feed: SystemFeed; plugin: FeedPlugin; model: EmsModel } {
  const c = clock ?? systemClock();
  let wrong = 0;
  let gaps = 0;
  const model: EmsModel = { chunkNo: new Map(), silent: new Map() };
  const feed = new SystemFeed({
    system: 'EMS',
    clock: c,
    wrongIdentity: (type, p) => {
      const moved = { ...p, subjectCode: `NO-SUCH-ROOM-${(++wrong).toString()}` };
      return type === 'ems.series_chunk' ? rehashed(moved) : moved;
    },
  });
  const key = (room: unknown, tag: unknown) => `${String(room)}/${String(tag)}`;

  /** Publishes the EMS's own FEED_GAP occurrence of a room's sensor (RAISED or CLEARED). */
  function gapAlarm(room: string, tag: string, transition: 'RAISED' | 'CLEARED', occurrenceId: string) {
    const payload = {
      subjectKind: 'AREA', subjectCode: room, occurrenceId, transition, alarmCode: 'FEED_GAP', severity: '700', tag, value: null, limit: null, limitKind: 'STATE',
      message: transition === 'RAISED' ? `the ${tag} sensor of room ${room} stopped reporting (feed gap)` : `the ${tag} sensor of room ${room} reports again`,
      occurredAt: c.nowUs().toString(),
    };
    const parsed = EMS.inbound['ems.alarm']?.versions['1']?.safeParse(payload);
    if (!parsed?.success) throw new Error(`the FEED_GAP alarm does not match the EMS contract: ${parsed?.error.message ?? 'no schema'}`);
    return feed.publish('ems.alarm', `${room}/${occurrenceId}`, parsed.data as Record<string, unknown>);
  }

  const base = contractPlugin(feed, EMS, {
    prefix: 'ems',
    title: 'EMS simulator',
    routes: [
      {
        path: '/ems/v1/samples',
        messageType: 'ems.series_chunk',
        recordId: (p) => key(p['subjectCode'], p['tag']),
        complete(body) {
          const samples = Array.isArray(body['samples']) ? body['samples'] : [];
          const no = (model.chunkNo.get(key(body['roomCode'], body['tag'])) ?? 0) + 1;
          const chunk = {
            subjectKind: 'AREA' as const,
            subjectCode: typeof body['roomCode'] === 'string' ? body['roomCode'] : '',
            tag: typeof body['tag'] === 'string' ? body['tag'] : '',
            unit: unitOf(body['tag']) ?? '',
            chunkNo: no.toString(),
            samples: samples.map((s: unknown) => (isRecord(s) && typeof s['raw'] === 'string' ? nativeSample(s['raw'], typeof s['status'] === 'string' ? s['status'] : '0x00000000', c.nowUs()) : s)) as NativeSample[],
          };
          return { ...chunk, chunkHash: seriesChunkHash(chunk) };
        },
        published(p) {
          model.chunkNo.set(key(p['subjectCode'], p['tag']), Number(p['chunkNo']));
        },
      },
      {
        path: '/ems/v1/alarms',
        messageType: 'ems.alarm',
        recordId: (p) => `${String(p['subjectCode'])}/${String(p['occurrenceId'])}`,
        complete: (b) => ({
          subjectKind: 'AREA', subjectCode: b['roomCode'], occurrenceId: b['occurrenceId'], transition: b['transition'], alarmCode: b['alarmCode'], severity: b['severity'],
          tag: b['tag'] ?? null, value: b['value'] ?? null, limit: b['limit'] ?? null, limitKind: b['limitKind'] ?? null, message: b['message'], occurredAt: c.nowUs().toString(),
        }),
      },
    ],
    consoleRows: () => [
      ['Room sensors', [...model.chunkNo].map(([k, n]) => `${k} chunk ${n.toString()}`).join(', ') || 'none yet'],
      ['Sensors not reporting (FEED_GAP)', [...model.silent.keys()].join(', ') || 'none'],
    ],
    state: () => ({ chunkNo: Object.fromEntries(model.chunkNo), silent: Object.fromEntries(model.silent) }),
  });

  const plugin: FeedPlugin = {
    ...base,
    route(method, path, query, body) {
      if (method === 'POST' && path === '/ems/v1/samples' && isRecord(body) && model.silent.has(key(body['roomCode'], body['tag']))) {
        return { status: 409, body: { error: { code: 'SENSOR_SILENT', message: `the ${String(body['tag'])} sensor of room ${String(body['roomCode'])} is not reporting` } } };
      }
      if (method === 'POST' && path === '/ems/v1/sensor-gap') {
        if (!isRecord(body) || typeof body['roomCode'] !== 'string' || unitOf(body['tag']) === undefined || typeof body['on'] !== 'boolean') {
          return { status: 400, body: { error: { code: 'SCHEMA', message: `expected {roomCode, tag: ${EMS_TAGS.map((t) => t.tag).join('|')}, on: boolean}` } } };
        }
        const room = body['roomCode'];
        const tag = String(body['tag']);
        const k = key(room, tag);
        const open = model.silent.get(k);
        if (body['on'] === (open !== undefined)) return { status: 200, body: { unchanged: true } };
        const occurrence = open ?? `GAP-${(++gaps).toString()}-${c.nowUs().toString()}`;
        const env = gapAlarm(room, tag, body['on'] ? 'RAISED' : 'CLEARED', occurrence);
        if (body['on']) model.silent.set(k, occurrence);
        else model.silent.delete(k);
        return { status: 201, body: { sequenceNo: env.sequenceNo, idempotencyKey: env.idempotencyKey, payload: env.payload } };
      }
      return base.route(method, path, query, body);
    },
  };
  return { feed, plugin, model };
}

apps/simulators/src/erp/feed.ts.source:
/**
 * The message feed of the ERP and WMS simulators (Phase 6 slice 6a, builder A; ERP_WMS contract of
 * @ebmr/integration-sdk/adapter). The same protocol as the other system simulators: the eBMR adapter pulls the
 * envelopes after the last sequence number it handled, asks the heartbeat, and submits the reconciliation the feed
 * computes over what it published (counts and checksum per period of source time, DI-31 "no silent loss").
 *
 * Faults (outline: feed gap, stale value, malformed, duplicate, out-of-order, wrong batch, link cut mid-transfer, slow
 * answer, stale mirror), each switched on and off by the console or POST /api/fault:
 *   FEED_GAP      the feed delivers nothing while the data keeps changing (the head moves on; delivered when off)
 *   STALE_VALUE   a change is published with a source time older than the record's previous message
 *   MALFORMED     a published payload carries a field the contract does not know
 *   DUPLICATE     every page delivers the last message the adapter already has again (same key and hash)
 *   OUT_OF_ORDER  the messages of a page arrive in reverse order
 *   WRONG_BATCH   a published payload names a lot or material the eBMR does not hold
 *   LINK_CUT      the answer is cut off mid-transfer (half the body, then the connection is destroyed)
 *   SLOW          the answer comes after `slowMs`, past the adapter's timeout
 *   STALE_MIRROR  the heartbeat stops (503) while the feed still answers: the data stays, its freshness goes
 * SIMULATOR, DEMO-ONLY. No kernel or database import (dependency rule gateway-and-simulators-no-db).
 */
import { rawPayloadHash, reconciliationChecksum, type ReconciliationSubmission } from '@ebmr/integration-sdk/adapter';

export const FEED_FAULTS = ['FEED_GAP', 'STALE_VALUE', 'MALFORMED', 'DUPLICATE', 'OUT_OF_ORDER', 'WRONG_BATCH', 'LINK_CUT', 'SLOW', 'STALE_MIRROR'] as const;
export type FeedFault = (typeof FEED_FAULTS)[number];

export interface ErpWmsEnvelope {
  sourceSystem: 'ERP_WMS';
  messageType: string;
  sourceRecordId: string;
  sourceTimestamp: string;
  sequenceNo: string;
  idempotencyKey: string;
  schemaVersion: string;
  payloadHash: string;
  payload: Record<string, unknown>;
}

export interface FeedPage {
  messages: ErpWmsEnvelope[];
  head: string;
}

export interface FeedClock {
  nowUs(): bigint;
}

/** The system clock, strictly increasing (two messages never share a source time). */
export function systemClock(): FeedClock {
  let last = 0n;
  return {
    nowUs() {
      const t = BigInt(Date.now()) * 1000n;
      last = t > last ? t : last + 1n;
      return last;
    },
  };
}

/** The identity fields a WRONG_BATCH message names wrongly (lot, material, product). */
const IDENTITY_FIELDS = ['lotNumber', 'materialCode', 'productCode'] as const;

export class ErpWmsFeed {
  readonly faults = new Set<FeedFault>();
  slowMs = 3000;
  private readonly clock: FeedClock;
  private readonly name: string;
  private readonly messages: ErpWmsEnvelope[] = [];
  private readonly lastTimeOf = new Map<string, bigint>();

  /** `name` (ERP or WMS) prefixes the idempotency keys: the two feeds are two adapters with their own sequences. */
  constructor(name: string, clock: FeedClock = systemClock()) {
    this.name = name;
    this.clock = clock;
  }

  /** Publishes one message (the content faults apply while they are on). */
  publish(messageType: string, sourceRecordId: string, payload: Record<string, unknown>): ErpWmsEnvelope {
    const seq = this.messages.length + 1;
    let body = payload;
    if (this.faults.has('MALFORMED')) body = { ...body, simulatorExtra: 'not in the contract' };
    if (this.faults.has('WRONG_BATCH')) {
      body = { ...body };
      for (const f of IDENTITY_FIELDS) if (f in body) body[f] = `XX-UNKNOWN-${seq.toString()}`;
    }
    const recordKey = `${messageType}|${sourceRecordId}`;
    const previous = this.lastTimeOf.get(recordKey);
    let ts = this.clock.nowUs();
    if (this.faults.has('STALE_VALUE') && previous !== undefined) ts = previous - 1n;
    else this.lastTimeOf.set(recordKey, ts);
    const text = JSON.stringify(body);
    const env: ErpWmsEnvelope = {
      sourceSystem: 'ERP_WMS',
      messageType,
      sourceRecordId,
      sourceTimestamp: ts.toString(),
      sequenceNo: seq.toString(),
      idempotencyKey: `${this.name}-${seq.toString()}-${rawPayloadHash(text).slice(0, 12)}`,
      schemaVersion: '1',
      payloadHash: rawPayloadHash(text),
      payload: body,
    };
    this.messages.push(env);
    return env;
  }

  head(): bigint {
    return BigInt(this.messages.length);
  }

  published(): readonly ErpWmsEnvelope[] {
    return this.messages;
  }

  /** The messages after `after` (at most `limit`), with the delivery faults applied. */
  page(after: bigint, limit: number): FeedPage {
    const head = this.head().toString();
    if (this.faults.has('FEED_GAP')) return { messages: [], head };
    let out = this.messages.filter((m) => BigInt(m.sequenceNo) > after).slice(0, Math.max(1, Math.min(limit, 500)));
    if (this.faults.has('OUT_OF_ORDER')) out = [...out].reverse();
    if (this.faults.has('DUPLICATE') && after > 0n) {
      const again = this.messages[Number(after) - 1];
      if (again) out = [again, ...out];
    }
    return { messages: out, head };
  }

  heartbeatOk(): boolean {
    return !this.faults.has('STALE_MIRROR');
  }

  /** The source's own count and checksum of what it published in [fromUs, toUs) of source time. */
  reconciliation(fromUs: bigint, toUs: bigint): ReconciliationSubmission {
    const inPeriod = this.messages.filter((m) => BigInt(m.sourceTimestamp) >= fromUs && BigInt(m.sourceTimestamp) < toUs);
    const { count, checksum } = reconciliationChecksum(inPeriod.map((m) => ({ idempotencyKey: m.idempotencyKey, payloadHash: m.payloadHash })));
    return { periodFrom: fromUs.toString(), periodTo: toUs.toString(), sourceCount: count, sourceChecksum: checksum };
  }
}

apps/simulators/src/erp/model.ts.source:
/**
 * The ERP simulator's routes (Phase 6 slice 6a, builder A; ERP_WMS contract): the ERP publishes production orders with
 * their BOM, material and product masters and shipments on its feed (each body checked with the contract's payload
 * schema), and receives the eBMR's outbound messages (stock blocks, lot statuses, goods issues, yields), de-duplicated
 * by message id. SIMULATOR, DEMO-ONLY.
 *
 *   POST /erp/v1/production-orders | /materials | /products | /shipments   201 {sequenceNo, idempotencyKey}
 *   POST /erp/v1/outbound {messageId, topic, payload}   200 {erpReference} (the adapter's delivery; LINK_CUT and SLOW apply)
 *   GET  /erp/v1/outbound                               the messages received, in order
 */
import { randomUUID } from 'node:crypto';
import { ERP_WMS } from '@ebmr/integration-sdk/adapter';
import type { ErpWmsFeed } from './feed.ts';
import type { SimRoutes } from './server.ts';

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

export interface ReceivedOutbound {
  messageId: string;
  topic: string;
  payload: Record<string, unknown>;
  erpReference: string;
  /** How many times the eBMR sent it (redeliveries are acknowledged with the same reference). */
  deliveries: number;
}

/** A publish route checked with the contract: 201 with the envelope's numbers, or 400 naming what is wrong. */
export function publisher(feed: ErpWmsFeed, messageType: string, recordId: (p: Record<string, unknown>) => string) {
  return (body: unknown): { status: number; body: unknown } => {
    const schema = ERP_WMS.inbound[messageType]?.versions['1'];
    const parsed = schema?.safeParse(body);
    if (!parsed?.success) {
      return { status: 400, body: { error: { code: 'SCHEMA', message: parsed ? parsed.error.issues.map((i) => `${i.path.map(String).join('.')}: ${i.message}`).join('; ') : 'unknown type' } } };
    }
    const payload = parsed.data as Record<string, unknown>;
    const env = feed.publish(messageType, recordId(payload), payload);
    return { status: 201, body: { sequenceNo: env.sequenceNo, idempotencyKey: env.idempotencyKey } };
  };
}

export function erpRoutes(feed: ErpWmsFeed): SimRoutes & { outbound: ReceivedOutbound[] } {
  const outbound: ReceivedOutbound[] = [];
  const publish: Record<string, (body: unknown) => { status: number; body: unknown }> = {
    '/production-orders': publisher(feed, 'erp.production_order', (p) => String(p['orderNumber'])),
    '/materials': publisher(feed, 'erp.material_master', (p) => String(p['materialCode'])),
    '/products': publisher(feed, 'erp.product_master', (p) => `${String(p['productCode'])}|${String(p['strength'])}`),
    '/shipments': publisher(feed, 'erp.shipment', (p) => String(p['shipmentId'])),
  };
  return {
    prefix: 'erp',
    title: 'ERP simulator (ERP_WMS feed and outbound)',
    outbound,
    route(method, path, _query, body) {
      const p = publish[path];
      if (p && method === 'POST') return p(body);
      if (path === '/outbound' && method === 'GET') return { status: 200, body: { received: outbound } };
      if (path === '/outbound' && method === 'POST') {
        if (!isRecord(body) || typeof body['messageId'] !== 'string' || typeof body['topic'] !== 'string' || !isRecord(body['payload'])
            || !ERP_WMS.outbound.includes(body['topic'])) {
          return { status: 400, body: { error: { code: 'SCHEMA', message: `expected {messageId, topic (${ERP_WMS.outbound.join('|')}), payload}` } }, adapter: true };
        }
        const seen = outbound.find((o) => o.messageId === body['messageId']);
        if (seen) {
          seen.deliveries += 1;
          return { status: 200, body: { erpReference: seen.erpReference }, adapter: true };
        }
        const entry: ReceivedOutbound = { messageId: body['messageId'], topic: body['topic'], payload: body['payload'], erpReference: `ERP-${randomUUID().slice(0, 8).toUpperCase()}`, deliveries: 1 };
        outbound.push(entry);
        return { status: 200, body: { erpReference: entry.erpReference }, adapter: true };
      }
      return undefined;
    },
    consoleRows: () => [
      ['Messages published', feed.head().toString()],
      ['Outbound messages received', outbound.length.toString()],
      ['Stock blocks received', outbound.filter((o) => o.topic === 'erp.stock_block').length.toString()],
    ],
    state: () => ({ outbound }),
  };
}

apps/simulators/src/erp/server.ts.source:
/**
 * The HTTP server of the ERP and WMS simulators (Phase 6 slice 6a, builder A; no third-party dependencies). The eBMR's
 * ERP/WMS adapter worker is its client:
 *
 *   GET  /<erp|wms>/v1/feed?after=N&limit=M     200 {messages, head}: the envelopes after sequence N
 *   GET  /<erp|wms>/v1/heartbeat                200 {head}; 503 while STALE_MIRROR is on
 *   GET  /<erp|wms>/v1/reconciliation?from&to   200 ReconciliationSubmission over [from, to) of source time
 *   ...  the system's own routes (erp/model.ts, wms/model.ts)
 *
 * Control for tests and the demo: POST /api/fault {fault, on, slowMs?}; GET /api/state; GET / a plain-HTML console with
 * a button per fault. LINK_CUT and SLOW act on the feed and on the routes the adapter calls. SIMULATOR, DEMO-ONLY.
 */
import { createServer, type IncomingMessage, type Server, type ServerResponse } from 'node:http';
import { FEED_FAULTS, type ErpWmsFeed, type FeedFault } from './feed.ts';

const BODY_LIMIT = 1024 * 1024;

export class SimRefusal extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
  ) {
    super(message);
  }
}

export interface SimRoutes {
  /** 'erp' or 'wms'. */
  prefix: string;
  title: string;
  /** The system's own routes under /<prefix>/v1; undefined when the path is not one of them. `adapter` answers obey LINK_CUT and SLOW. */
  route(method: string, path: string, query: URLSearchParams, body: unknown): { status: number; body: unknown; adapter?: boolean } | undefined;
  consoleRows(): [string, string][];
  state(): unknown;
}

export interface RunningErpWmsSimulator {
  feed: ErpWmsFeed;
  port: number;
  url: string;
  close(): Promise<void>;
}

const esc = (s: string): string => s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0).toString()};`);
const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const WHOLE = /^(0|[1-9][0-9]{0,17})$/;
const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

async function readJson(req: IncomingMessage): Promise<unknown> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const c of req) {
    size += (c as Buffer).length;
    if (size > BODY_LIMIT) throw new SimRefusal(413, 'TOO_LARGE', 'the body is too large');
    chunks.push(c as Buffer);
  }
  const text = Buffer.concat(chunks).toString('utf8');
  try {
    return text === '' ? {} : (JSON.parse(text) as unknown);
  } catch {
    throw new SimRefusal(400, 'SCHEMA', 'the body is not JSON');
  }
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json', 'cache-control': 'no-store' });
  res.end(JSON.stringify(body));
}

export async function startErpWmsSimulator(feed: ErpWmsFeed, routes: SimRoutes, http: { host: string; port: number }): Promise<RunningErpWmsSimulator> {
  const base = `/${routes.prefix}/v1`;

  /** An answer to the adapter with the delivery faults: late (SLOW) or cut off mid-transfer (LINK_CUT). */
  async function deliver(res: ServerResponse, status: number, body: unknown): Promise<void> {
    if (feed.faults.has('SLOW')) await sleep(feed.slowMs);
    const text = JSON.stringify(body);
    if (feed.faults.has('LINK_CUT')) {
      res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(text).toString() });
      res.write(text.slice(0, Math.max(1, Math.floor(text.length / 2))));
      res.socket?.destroy();
      return;
    }
    send(res, status, body);
  }

  function consoleHtml(): string {
    const rows: [string, string][] = [['Head (sequence)', feed.head().toString()], ['Faults on', [...feed.faults].join(', ') || 'none'], ...routes.consoleRows()];
    const table = rows.map(([k, v]) => `<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join('');
    const buttons = FEED_FAULTS.map((f) => {
      const on = feed.faults.has(f);
      return `<li><button type="button" data-fault="${esc(f)}" data-on="${on ? 'false' : 'true'}">${on ? 'Switch off' : 'Switch on'}</button> ${esc(f)}: <strong>${on ? 'ON' : 'off'}</strong></li>`;
    }).join('');
    return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(routes.title)}</title>
<style>body{font-family:system-ui,sans-serif;margin:16px;background:#fff;color:#111}.banner{background:#fde68a;padding:8px 12px;font-weight:700;border-radius:6px}table{border-collapse:collapse}td,th{border-bottom:1px solid #ddd;padding:4px 8px;text-align:left;font-family:ui-monospace,monospace}button{min-height:44px;margin:4px}</style></head>
<body><p class="banner">SIMULATOR (DEMO-ONLY): ${esc(routes.title)}</p><h1>${esc(routes.title)}</h1>
<table>${table}</table><h2>Faults</h2><ul>${buttons}</ul>
<script>document.querySelectorAll('button[data-fault]').forEach(function(b){b.addEventListener('click',function(){fetch('/api/fault',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({fault:b.dataset.fault,on:b.dataset.on==='true'})}).then(function(){location.reload()})})})</script>
</body></html>`;
  }

  async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const url = new URL(req.url ?? '/', 'http://sim');
    const path = url.pathname;
    const method = req.method ?? 'GET';
    if (method === 'GET' && path === '/') {
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
      res.end(consoleHtml());
      return;
    }
    if (method === 'GET' && path === '/api/state') return send(res, 200, { head: feed.head().toString(), faults: [...feed.faults], model: routes.state() });
    if (method === 'POST' && path === '/api/fault') {
      const body = await readJson(req);
      if (!isRecord(body) || !FEED_FAULTS.includes(body['fault'] as FeedFault) || typeof body['on'] !== 'boolean') {
        throw new SimRefusal(400, 'SCHEMA', `expected {fault: ${FEED_FAULTS.join('|')}, on: boolean, slowMs?}`);
      }
      if (body['on']) feed.faults.add(body['fault'] as FeedFault);
      else feed.faults.delete(body['fault'] as FeedFault);
      if (typeof body['slowMs'] === 'number' && Number.isInteger(body['slowMs']) && body['slowMs'] >= 0) feed.slowMs = body['slowMs'];
      return send(res, 200, { faults: [...feed.faults] });
    }
    if (!path.startsWith(`${base}/`)) throw new SimRefusal(404, 'NOT_FOUND', `no route ${method} ${path}`);
    const sub = path.slice(base.length);
    if (method === 'GET' && sub === '/feed') {
      const after = url.searchParams.get('after') ?? '0';
      const limit = url.searchParams.get('limit') ?? '100';
      if (!WHOLE.test(after) || !/^[1-9][0-9]{0,3}$/.test(limit)) throw new SimRefusal(400, 'SCHEMA', 'after is a sequence number and limit 1 to 9999');
      return deliver(res, 200, feed.page(BigInt(after), Number(limit)));
    }
    if (method === 'GET' && sub === '/heartbeat') {
      return feed.heartbeatOk() ? send(res, 200, { head: feed.head().toString() }) : send(res, 503, { error: { code: 'STALE_MIRROR', message: 'the synchronisation of the source stopped' } });
    }
    if (method === 'GET' && sub === '/reconciliation') {
      const from = url.searchParams.get('from') ?? '';
      const to = url.searchParams.get('to') ?? '';
      if (!WHOLE.test(from) || !WHOLE.test(to) || BigInt(from) >= BigInt(to)) throw new SimRefusal(400, 'SCHEMA', 'from < to, epoch microseconds');
      return deliver(res, 200, feed.reconciliation(BigInt(from), BigInt(to)));
    }
    const body = method === 'POST' ? await readJson(req) : undefined;
    const answer = routes.route(method, sub, url.searchParams, body);
    if (!answer) throw new SimRefusal(404, 'NOT_FOUND', `no route ${method} ${path}`);
    if (answer.adapter) return deliver(res, answer.status, answer.body);
    return send(res, answer.status, answer.body);
  }

  const server: Server = createServer((req, res) => {
    handle(req, res).catch((error: unknown) => {
      if (res.headersSent) return;
      if (error instanceof SimRefusal) send(res, error.status, { error: { code: error.code, message: error.message } });
      else send(res, 500, { error: { code: 'INTERNAL', message: error instanceof Error ? error.message : String(error) } });
    });
  });
  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(http.port, http.host, () => resolve());
  });
  const addr = server.address();
  const port = typeof addr === 'object' && addr ? addr.port : http.port;
  return {
    feed,
    port,
    url: `http://${http.host}:${port.toString()}${base}`,
    close: () =>
      new Promise<void>((resolve) => {
        server.closeAllConnections();
        server.close(() => resolve());
      }),
  };
}

/** host:port from an environment value (loopback by default). */
export function address(value: string | undefined, fallback: string): { host: string; port: number } {
  const text = value && value !== '' ? value : fallback;
  const m = /^(.+):(\d+)$/.exec(text);
  if (!m) throw new Error(`not a host:port address: ${text}`);
  return { host: m[1] ?? '127.0.0.1', port: Number(m[2]) };
}

