apps/simulators/src/serialisation/server.source:
/**
 * The serialisation L3 stub's HTTP server (Phase 3 slice 4a; no third-party dependencies; default 127.0.0.1:4041).
 * The tablets server is its client:
 *
 *   POST /l3/v1/pools                     PoolRequest -> 201 PoolResponse (200 for a repeat of the same request)
 *   POST /l3/v1/pools/:poolId/events      SerialEventsRequest -> 200 {accepted}; refused whole: 404, 409, 422
 *   GET  /l3/v1/pools/:poolId/report      200 PoolReport
 *   POST /l3/v1/pools/:poolId/reject      {reason} -> 201 DecommissionTask (D-S4-3; 200 for a repeat)
 *   GET  /l3/v1/decommission-tasks        200 {tasks}
 *   GET  /l3/v1/pools                     200 {pools}: summaries (the console and the tests)
 *
 * Phase 6 slice 6c (the L3/L4 simulator; PR-42, D-P6c-1):
 *   GET  /l3/v1/feed?after=N&limit=M      200 {messages, head}: the L3 feed the eBMR's L3 adapter pulls
 *   GET  /l3/v1/heartbeat                 200 {head}; 503 while STALE_REPORT (or STALE_MIRROR) is on
 *   GET  /l3/v1/reconciliation?from&to    200 ReconciliationSubmission over [from, to) of source time
 *   GET  /l3/v1/serials/:serial           200 SerialQueryAnswer; 404 for an unknown serial
 *   POST /l3/v1/aggregations              {poolId, parentId, childCount, action?} -> 201, published as l3.aggregation
 *   POST /l3/v1/decommission-tasks/:id/done   -> 200 DecommissionTask DONE, published as l3.decommission_task
 *   POST /l3/v1/pools/:poolId/profile     {lot?, expiry?}: what the L3 profile carries for the pool's serials
 *
 * A refusal answers {error:{code, message}} (L3Error). Control for tests and the demo: POST /api/fault {fault, on}:
 * UNAVAILABLE makes every /l3 route answer 503; the L3 faults (model.ts L3_FAULTS) and the feed's content and delivery
 * faults (DUPLICATE, OUT_OF_ORDER, MALFORMED, WRONG_BATCH, STALE_VALUE) switch the same way; GET / is a plain-HTML
 * console. SIMULATOR, DEMO-ONLY.
 */
import { createServer, type IncomingMessage, type Server, type ServerResponse } from 'node:http';
import { PoolRequest, SerialEventsRequest } from '@ebmr/integration-sdk/serialisation';
import type { FeedFault } from '../system-feed/feed.ts';
import { L3_FAULTS, L3Refusal, L3Stub, type L3Fault, type L3StubOptions } from './model.ts';

/** The feed faults the L3 simulator switches as they are (the delivery of its feed). */
const L3_FEED_FAULTS = ['DUPLICATE', 'OUT_OF_ORDER', 'MALFORMED', 'WRONG_BATCH', 'STALE_VALUE'] as const;
const WHOLE = /^(0|[1-9][0-9]{0,17})$/;

export interface L3StubServerOptions extends L3StubOptions {
  http: { host: string; port: number };
}

export interface RunningL3Stub {
  stub: L3Stub;
  port: number;
  faults: Set<'UNAVAILABLE'>;
  close(): Promise<void>;
}

const BODY_LIMIT = 4 * 1024 * 1024;
const REASON = /^[\x20-\x7E]{1,500}$/;
const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const issues = (e: { issues: { path: PropertyKey[]; message: string }[] }): string => e.issues.map((i) => `${i.path.map(String).join('.')}: ${i.message}`).join('; ');

const esc = (s: string): string => s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

class BadRequest extends Error {}

async function readJson(req: IncomingMessage): Promise<unknown> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const c of req) {
    size += (c as Buffer).length;
    if (size > BODY_LIMIT) throw new BadRequest('the body is too large');
    chunks.push(c as Buffer);
  }
  const text = Buffer.concat(chunks).toString('utf8');
  try {
    return text === '' ? {} : (JSON.parse(text) as unknown);
  } catch {
    throw new BadRequest('the body is not JSON');
  }
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json', 'cache-control': 'no-store' });
  res.end(JSON.stringify(body));
}

function refuse(res: ServerResponse, status: number, code: string, message: string): void {
  send(res, status, { error: { code, message: message.slice(0, 500) } });
}

export async function startL3Stub(opts: L3StubServerOptions): Promise<RunningL3Stub> {
  const stub = new L3Stub(opts);
  const faults = new Set<'UNAVAILABLE'>();

  function consoleHtml(): string {
    const rows = stub
      .summaries()
      .map((p) => `<tr><td>${esc(p.poolId)}</td><td>${esc(p.packagingOrder)}</td><td>${esc(p.market)}</td><td>${esc(p.report.counts.issued)}</td><td>${esc(p.report.counts.COMMISSIONED)}</td><td>${esc(p.report.unexplained)}</td><td>${p.rejected ? 'REJECTED' : ''}</td></tr>`)
      .join('');
    return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="refresh" content="2"><title>L3 serialisation stub</title>
<style>body{font-family:system-ui,sans-serif;margin:16px;background:#fff;color:#111}.banner{background:#fde68a;padding:8px 12px;font-weight:700;border-radius:6px}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #ddd;padding:4px 8px;text-align:left;font-family:ui-monospace,monospace}</style></head>
<body><p class="banner">SIMULATOR (DEMO-ONLY): a stub of the site's L3 serialisation system.</p><h1>L3 serialisation stub</h1>
<p>${faults.has('UNAVAILABLE') ? 'UNAVAILABLE (answers 503)' : 'Available'}; ${stub.decommissionTasks().filter((t) => t.state === 'OPEN').length} decommissioning task(s) open; feed head ${esc(stub.feed.head().toString())}; faults on: ${esc([...stub.faults, ...stub.feed.faults].join(', ') || 'none')}.</p>
<table><thead><tr><th>Pool</th><th>Packaging order</th><th>Market</th><th>Issued</th><th>Commissioned</th><th>Unexplained</th><th></th></tr></thead><tbody>${rows}</tbody></table></body></html>`;
  }

  async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const url = new URL(req.url ?? '/', 'http://l3');
    const path = url.pathname;
    const method = req.method ?? 'GET';
    if (method === 'GET' && path === '/') {
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
      res.end(consoleHtml());
      return;
    }
    if (method === 'GET' && path === '/api/state') return send(res, 200, { head: stub.feed.head().toString(), faults: [...faults, ...stub.faults, ...stub.feed.faults], model: { pools: stub.summaries(), tasks: stub.decommissionTasks() } });
    if (method === 'POST' && path === '/api/fault') {
      const body = await readJson(req);
      const fault = isRecord(body) ? body['fault'] : undefined;
      const on = isRecord(body) ? body['on'] : undefined;
      if (typeof on !== 'boolean' || typeof fault !== 'string') return refuse(res, 400, 'SCHEMA', `expected {fault: UNAVAILABLE|${L3_FAULTS.join('|')}|${L3_FEED_FAULTS.join('|')}, on}`);
      if (fault === 'UNAVAILABLE') {
        if (on) faults.add('UNAVAILABLE');
        else faults.delete('UNAVAILABLE');
      } else if ((L3_FAULTS as readonly string[]).includes(fault)) {
        stub.setFault(fault as L3Fault, on);
      } else if ((L3_FEED_FAULTS as readonly string[]).includes(fault)) {
        if (on) stub.feed.faults.add(fault as FeedFault);
        else stub.feed.faults.delete(fault as FeedFault);
      } else {
        return refuse(res, 400, 'SCHEMA', `unknown fault ${fault.slice(0, 40)}`);
      }
      return send(res, 200, { faults: [...faults, ...stub.faults, ...stub.feed.faults] });
    }
    if (!path.startsWith('/l3/v1/')) return refuse(res, 404, 'NOT_FOUND', 'not found');
    if (faults.has('UNAVAILABLE')) return refuse(res, 503, 'UNAVAILABLE', 'the L3 system is unavailable');

    if (method === 'POST' && path === '/l3/v1/pools') {
      const body = PoolRequest.safeParse(await readJson(req));
      if (!body.success) return refuse(res, 400, 'SCHEMA', issues(body.error));
      const before = stub.summaries().length;
      const pool = stub.issue(body.data);
      return send(res, stub.summaries().length > before ? 201 : 200, pool);
    }
    if (method === 'GET' && path === '/l3/v1/pools') return send(res, 200, { pools: stub.summaries() });
    if (method === 'GET' && path === '/l3/v1/feed') {
      const after = url.searchParams.get('after') ?? '0';
      const limit = url.searchParams.get('limit') ?? '100';
      if (!WHOLE.test(after) || !/^[1-9][0-9]{0,2}$/.test(limit)) return refuse(res, 400, 'SCHEMA', 'after is a whole number, limit 1 to 999');
      return send(res, 200, stub.feed.page(BigInt(after), Number(limit)));
    }
    if (method === 'GET' && path === '/l3/v1/heartbeat') {
      if (!stub.feed.heartbeatOk()) return refuse(res, 503, 'NO_HEARTBEAT', 'the L3 heartbeat has stopped');
      return send(res, 200, { head: stub.feed.head().toString() });
    }
    if (method === 'GET' && path === '/l3/v1/reconciliation') {
      const from = url.searchParams.get('from') ?? '';
      const to = url.searchParams.get('to') ?? '';
      if (!WHOLE.test(from) || !WHOLE.test(to) || BigInt(from) >= BigInt(to)) return refuse(res, 400, 'SCHEMA', 'from and to are epoch microseconds, from < to');
      return send(res, 200, stub.feed.reconciliation(BigInt(from), BigInt(to)));
    }
    if (method === 'POST' && path === '/l3/v1/aggregations') {
      const body = await readJson(req);
      if (!isRecord(body) || typeof body['poolId'] !== 'string' || typeof body['parentId'] !== 'string' || typeof body['childCount'] !== 'string'
          || (body['action'] !== undefined && body['action'] !== 'ADD' && body['action'] !== 'DELETE')) {
        return refuse(res, 400, 'SCHEMA', 'expected {poolId, parentId, childCount, action?}');
      }
      return send(res, 201, stub.aggregate({ poolId: body['poolId'], parentId: body['parentId'], childCount: body['childCount'], ...(body['action'] ? { action: body['action'] } : {}) }));
    }
    const done = /^\/l3\/v1\/decommission-tasks\/([^/]+)\/done$/.exec(path);
    if (done && method === 'POST') return send(res, 200, stub.completeTask(decodeURIComponent(done[1] ?? '')));
    const serial = /^\/l3\/v1\/serials\/([^/]+)$/.exec(path);
    if (serial && method === 'GET') return send(res, 200, stub.query(decodeURIComponent(serial[1] ?? '')));
    if (method === 'GET' && path === '/l3/v1/decommission-tasks') return send(res, 200, { tasks: stub.decommissionTasks() });
    const m = /^\/l3\/v1\/pools\/([^/]+)\/(events|report|reject|profile)$/.exec(path);
    if (!m) return refuse(res, 404, 'NOT_FOUND', 'not found');
    const poolId = decodeURIComponent(m[1] ?? '');
    const what = m[2];
    if (what === 'report' && method === 'GET') return send(res, 200, stub.report(poolId));
    if (what === 'profile' && method === 'POST') {
      const body = await readJson(req);
      const lot = isRecord(body) ? body['lot'] : undefined;
      const expiry = isRecord(body) ? body['expiry'] : undefined;
      if ((lot !== undefined && (typeof lot !== 'string' || !/^[\x20-\x7E]{1,64}$/.test(lot))) || (expiry !== undefined && (typeof expiry !== 'string' || !/^\d{4}-(0[1-9]|1[0-2])$/.test(expiry)))) {
        return refuse(res, 400, 'SCHEMA', 'expected {lot?, expiry? (YYYY-MM)}');
      }
      stub.setProfile(poolId, { ...(lot ? { lot } : {}), ...(expiry ? { expiry } : {}) });
      return send(res, 200, { poolId });
    }
    if (what === 'events' && method === 'POST') {
      const body = SerialEventsRequest.safeParse(await readJson(req));
      if (!body.success) return refuse(res, 400, 'SCHEMA', issues(body.error));
      return send(res, 200, { accepted: stub.applyEvents(poolId, body.data.events).toString() });
    }
    if (what === 'reject' && method === 'POST') {
      const body = await readJson(req);
      const reason = isRecord(body) && Object.keys(body).length === 1 ? body['reason'] : undefined;
      if (typeof reason !== 'string' || !REASON.test(reason)) return refuse(res, 400, 'SCHEMA', 'expected {reason}');
      const before = stub.decommissionTasks().length;
      const task = stub.reject(poolId, reason);
      return send(res, stub.decommissionTasks().length > before ? 201 : 200, task);
    }
    return refuse(res, 405, 'METHOD', `${method} is not allowed on ${path}`);
  }

  const server: Server = createServer((req, res) => {
    void handle(req, res).catch((error: unknown) => {
      if (error instanceof L3Refusal) return refuse(res, error.status, error.code, error.message);
      if (error instanceof BadRequest) return refuse(res, 400, 'SCHEMA', error.message);
      refuse(res, 500, 'INTERNAL', error instanceof Error ? error.message : String(error));
    });
  });
  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(opts.http.port, opts.http.host, () => resolve());
  });
  const a = server.address();
  return {
    stub,
    port: a && typeof a === 'object' ? a.port : opts.http.port,
    faults,
    async close() {
      server.closeAllConnections();
      await new Promise<void>((r) => server.close(() => r()));
    },
  };
}

apps/simulators/src/system-feed/feed.ts.source:
/**
 * The message feed every system simulator of slice 6a builder B serves (QMS, LIMS, LMS, CMMS; Phase 6 slice 6a;
 * @ebmr/integration-sdk/adapter). The simulator's model publishes a message whenever its data changes; the eBMR adapter
 * pulls the feed after the last sequence number it handled, asks for the heartbeat, and submits the reconciliation the
 * feed computes over what it published (counts and checksum per period of source time, DI-31 "no silent loss").
 *
 * Faults (outline: feed gap, stale value, malformed, duplicate, out-of-order, wrong batch, link cut mid-transfer, slow
 * answer, stale mirror), each switched on and off by the console or POST /api/fault:
 *   FEED_GAP      the feed delivers nothing while the data keeps changing (the head moves on; delivered when off)
 *   STALE_VALUE   a change is published with a source time older than the record's previous message
 *   MALFORMED     a published payload carries a field the contract does not know
 *   DUPLICATE     every page delivers the last message the adapter already has again (same key and hash)
 *   OUT_OF_ORDER  the messages of a page arrive in reverse order
 *   WRONG_BATCH   a published payload names a lot, unit or person the eBMR does not hold (the system's own field)
 *   LINK_CUT      the feed answer is cut off mid-transfer (half the body, then the connection is destroyed)
 *   SLOW          the feed answer comes after `slowMs`, past the adapter's timeout
 *   STALE_MIRROR  the heartbeat stops (503) while the feed still answers: the data stays, its freshness goes
 * SIMULATOR, DEMO-ONLY. No kernel or database import (dependency rule gateway-and-simulators-no-db).
 */
import { rawPayloadHash, reconciliationChecksum, type ReconciliationSubmission } from '@ebmr/integration-sdk/adapter';

export const FEED_FAULTS = ['FEED_GAP', 'STALE_VALUE', 'MALFORMED', 'DUPLICATE', 'OUT_OF_ORDER', 'WRONG_BATCH', 'LINK_CUT', 'SLOW', 'STALE_MIRROR'] as const;
export type FeedFault = (typeof FEED_FAULTS)[number];

export type FeedSystem = 'QMS' | 'LIMS' | 'LMS' | 'CMMS' | 'EMS' | 'L3';

export interface FeedEnvelope {
  sourceSystem: FeedSystem;
  messageType: string;
  sourceRecordId: string;
  sourceTimestamp: string;
  sequenceNo: string;
  idempotencyKey: string;
  schemaVersion: string;
  payloadHash: string;
  payload: Record<string, unknown>;
}

export interface FeedClock {
  nowUs(): bigint;
}

/** The system clock, strictly increasing (two messages never share a source time). */
export function systemClock(): FeedClock {
  let last = 0n;
  return {
    nowUs() {
      const t = BigInt(Date.now()) * 1000n;
      last = t > last ? t : last + 1n;
      return last;
    },
  };
}

export interface FeedPage {
  messages: FeedEnvelope[];
  /** The highest sequence number published (the adapter is caught up when it has handled everything up to it). */
  head: string;
}

export interface FeedOptions {
  system: FeedSystem;
  clock?: FeedClock;
  /** Replaces the identity the system names (lot, unit, person) by one the eBMR does not hold (WRONG_BATCH). */
  wrongIdentity: (messageType: string, payload: Record<string, unknown>) => Record<string, unknown>;
}

export class SystemFeed {
  readonly system: FeedSystem;
  readonly faults = new Set<FeedFault>();
  slowMs = 3000;
  private readonly clock: FeedClock;
  private readonly wrongIdentity: FeedOptions['wrongIdentity'];
  private readonly messages: FeedEnvelope[] = [];
  private readonly lastTimeOf = new Map<string, bigint>();

  constructor(opts: FeedOptions) {
    this.system = opts.system;
    this.clock = opts.clock ?? systemClock();
    this.wrongIdentity = opts.wrongIdentity;
  }

  /** Publishes one message (the content faults apply while they are on). */
  publish(messageType: string, sourceRecordId: string, payload: Record<string, unknown>): FeedEnvelope {
    const seq = this.messages.length + 1;
    let body = payload;
    if (this.faults.has('MALFORMED')) body = { ...body, simulatorExtra: 'not in the contract' };
    if (this.faults.has('WRONG_BATCH')) body = this.wrongIdentity(messageType, body);
    const recordKey = `${messageType}|${sourceRecordId}`;
    const previous = this.lastTimeOf.get(recordKey);
    let ts = this.clock.nowUs();
    if (this.faults.has('STALE_VALUE') && previous !== undefined) ts = previous - 1n;
    else this.lastTimeOf.set(recordKey, ts);
    const text = JSON.stringify(body);
    const env: FeedEnvelope = {
      sourceSystem: this.system,
      messageType,
      sourceRecordId,
      sourceTimestamp: ts.toString(),
      sequenceNo: seq.toString(),
      idempotencyKey: `${this.system}-${seq.toString()}-${rawPayloadHash(text).slice(0, 12)}`,
      schemaVersion: '1',
      payloadHash: rawPayloadHash(text),
      payload: body,
    };
    this.messages.push(env);
    return env;
  }

  head(): bigint {
    return BigInt(this.messages.length);
  }

  published(): readonly FeedEnvelope[] {
    return this.messages;
  }

  /** The messages after `after` (at most `limit`), with the delivery faults applied. */
  page(after: bigint, limit: number): FeedPage {
    const head = this.head().toString();
    if (this.faults.has('FEED_GAP')) return { messages: [], head };
    let out = this.messages.filter((m) => BigInt(m.sequenceNo) > after).slice(0, Math.max(1, Math.min(limit, 500)));
    if (this.faults.has('OUT_OF_ORDER')) out = [...out].reverse();
    if (this.faults.has('DUPLICATE') && after > 0n) {
      const again = this.messages[Number(after) - 1];
      if (again) out = [again, ...out];
    }
    return { messages: out, head };
  }

  heartbeatOk(): boolean {
    return !this.faults.has('STALE_MIRROR');
  }

  /** The source's own count and checksum of what it published in [fromUs, toUs) of source time. */
  reconciliation(fromUs: bigint, toUs: bigint): ReconciliationSubmission {
    const inPeriod = this.messages.filter((m) => BigInt(m.sourceTimestamp) >= fromUs && BigInt(m.sourceTimestamp) < toUs);
    const { count, checksum } = reconciliationChecksum(inPeriod.map((m) => ({ idempotencyKey: m.idempotencyKey, payloadHash: m.payloadHash })));
    return { periodFrom: fromUs.toString(), periodTo: toUs.toString(), sourceCount: count, sourceChecksum: checksum };
  }
}

apps/simulators/src/system-feed/plugin.t.source:
/**
 * A simulator plugin from its system contract (Phase 6 slice 6a, builder B): one POST route per inbound message type
 * that validates the body with the contract's payload schema, lets the model change its state, and publishes the
 * message on the feed. SIMULATOR, DEMO-ONLY.
 */
import type { SystemContract } from '@ebmr/integration-sdk/adapter';
import type { SystemFeed } from './feed.ts';
import type { FeedPlugin } from './server.ts';

export interface PublishRoute {
  /** The path after the prefix, e.g. '/qms/v1/deviations'. */
  path: string;
  messageType: string;
  /** The record's id in the source (the envelope's sourceRecordId). */
  recordId(payload: Record<string, unknown>): string;
  /** The model may complete the payload (a new version token) before it is checked and published. */
  complete?(body: Record<string, unknown>): Record<string, unknown>;
  /** Told the checked payload once it is published (the model keeps its state). */
  published?(payload: Record<string, unknown>): void;
}

export function contractPlugin(
  feed: SystemFeed,
  contract: SystemContract,
  o: { prefix: string; title: string; routes: PublishRoute[]; reads?: FeedPlugin['route']; consoleRows?: () => [string, string][]; state?: () => unknown },
): FeedPlugin {
  return {
    prefix: o.prefix,
    title: o.title,
    route(method, path, query, body) {
      const r = o.routes.find((x) => x.path === path);
      if (r && method === 'POST') {
        const schema = contract.inbound[r.messageType]?.versions['1'];
        const filled = r.complete && typeof body === 'object' && body !== null && !Array.isArray(body) ? r.complete(body as Record<string, unknown>) : body;
        const parsed = schema?.safeParse(filled);
        if (!parsed?.success) {
          return { status: 400, body: { error: { code: 'SCHEMA', message: parsed ? parsed.error.issues.map((i) => `${i.path.map(String).join('.')}: ${i.message}`).join('; ') : 'unknown type' } } };
        }
        const payload = parsed.data as Record<string, unknown>;
        const env = feed.publish(r.messageType, r.recordId(payload), payload);
        r.published?.(payload);
        return { status: 201, body: { sequenceNo: env.sequenceNo, idempotencyKey: env.idempotencyKey, payload: env.payload } };
      }
      return o.reads ? o.reads(method, path, query, body) : undefined;
    },
    consoleRows: o.consoleRows ?? (() => []),
    state: o.state ?? (() => ({})),
  };
}

apps/simulators/src/system-feed/server.t.source:
/**
 * The HTTP server of a feed simulator (QMS, LIMS, LMS, CMMS; Phase 6 slice 6a, builder B; no third-party dependencies).
 * The eBMR adapter worker is its client:
 *
 *   GET  /<sys>/v1/feed?after=N&limit=M     200 {messages, head}: the envelopes after sequence N (FeedPage)
 *   GET  /<sys>/v1/heartbeat                200 {head, atUs}; 503 while STALE_MIRROR is on
 *   GET  /<sys>/v1/reconciliation?from&to   200 ReconciliationSubmission over [from, to) of source time
 *   ...  the system's own routes (its plugin)
 *
 * Control for tests and the demo: POST /api/fault {fault, on, slowMs?}; GET /api/state; GET / a plain-HTML console.
 * LINK_CUT and SLOW act on the feed and on the system's read routes (a cut or a late answer). SIMULATOR, DEMO-ONLY.
 */
import { createServer, type IncomingMessage, type Server, type ServerResponse } from 'node:http';
import { FEED_FAULTS, type FeedFault, type SystemFeed } from './feed.ts';

const BODY_LIMIT = 1024 * 1024;

export class SimRefusal extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
  ) {
    super(message);
  }
}

export interface FeedPlugin {
  /** The path prefix, e.g. 'qms'. */
  prefix: string;
  title: string;
  /** The system's own routes; undefined when the path is not one of them. `read` routes obey LINK_CUT and SLOW. */
  route(method: string, path: string, query: URLSearchParams, body: unknown): { status: number; body: unknown; read?: boolean } | undefined;
  /** Rows for the console: [label, value]. */
  consoleRows(): [string, string][];
  /** The model's state for GET /api/state. */
  state(): unknown;
}

export interface RunningFeedSimulator {
  feed: SystemFeed;
  port: number;
  close(): Promise<void>;
}

const esc = (s: string): string => s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const WHOLE = /^(0|[1-9][0-9]{0,17})$/;

async function readJson(req: IncomingMessage): Promise<unknown> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const c of req) {
    size += (c as Buffer).length;
    if (size > BODY_LIMIT) throw new SimRefusal(413, 'TOO_LARGE', 'the body is too large');
    chunks.push(c as Buffer);
  }
  const text = Buffer.concat(chunks).toString('utf8');
  try {
    return text === '' ? {} : (JSON.parse(text) as unknown);
  } catch {
    throw new SimRefusal(400, 'SCHEMA', 'the body is not JSON');
  }
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json', 'cache-control': 'no-store' });
  res.end(JSON.stringify(body));
}

const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

export async function startFeedSimulator(feed: SystemFeed, plugin: FeedPlugin, http: { host: string; port: number }): Promise<RunningFeedSimulator> {
  const base = `/${plugin.prefix}/v1`;

  /** A read answer with the delivery faults: late (SLOW) or cut off mid-transfer (LINK_CUT). */
  async function deliver(res: ServerResponse, body: unknown): Promise<void> {
    if (feed.faults.has('SLOW')) await sleep(feed.slowMs);
    const text = JSON.stringify(body);
    if (feed.faults.has('LINK_CUT')) {
      res.writeHead(200, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(text).toString() });
      res.write(text.slice(0, Math.max(1, Math.floor(text.length / 2))));
      res.socket?.destroy();
      return;
    }
    res.writeHead(200, { 'content-type': 'application/json', 'cache-control': 'no-store' });
    res.end(text);
  }

  function consoleHtml(): string {
    const rows: [string, string][] = [['Head (sequence)', feed.head().toString()], ['Faults on', [...feed.faults].join(', ') || 'none'], ...plugin.consoleRows()];
    const html = rows
      .map(([k, v]) => `<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`)
      .join('');
    const buttons = FEED_FAULTS.map((f) => `<li>${esc(f)}: ${feed.faults.has(f) ? 'ON' : 'off'}</li>`).join('');
    return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="refresh" content="2"><title>${esc(plugin.title)}</title>
<style>body{font-family:system-ui,sans-serif;margin:16px;background:#fff;color:#111}.banner{background:#fde68a;padding:8px 12px;font-weight:700;border-radius:6px}table{border-collapse:collapse}td,th{border-bottom:1px solid #ddd;padding:4px 8px;text-align:left;font-family:ui-monospace,monospace}</style></head>
<body><p class="banner">SIMULATOR (DEMO-ONLY): ${esc(plugin.title)}. Switch faults with POST /api/fault {"fault": "...", "on": true}.</p><h1>${esc(plugin.title)}</h1>
<table>${html}</table><h2>Faults</h2><ul>${buttons}</ul></body></html>`;
  }

  async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const url = new URL(req.url ?? '/', 'http://sim');
    const path = url.pathname;
    const method = req.method ?? 'GET';
    if (method === 'GET' && path === '/') {
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
      res.end(consoleHtml());
      return;
    }
    if (method === 'GET' && path === '/api/state') return send(res, 200, { head: feed.head().toString(), faults: [...feed.faults], model: plugin.state() });
    if (method === 'POST' && path === '/api/fault') {
      const body = await readJson(req);
      if (!isRecord(body) || !FEED_FAULTS.includes(body['fault'] as FeedFault) || typeof body['on'] !== 'boolean') {
        throw new SimRefusal(400, 'SCHEMA', `expected {fault: ${FEED_FAULTS.join('|')}, on: boolean, slowMs?}`);
      }
      if (body['on']) feed.faults.add(body['fault'] as FeedFault);
      else feed.faults.delete(body['fault'] as FeedFault);
      if (typeof body['slowMs'] === 'number' && Number.isInteger(body['slowMs']) && body['slowMs'] >= 0) feed.slowMs = body['slowMs'];
      return send(res, 200, { faults: [...feed.faults] });
    }
    if (method === 'GET' && path === `${base}/feed`) {
      const after = url.searchParams.get('after') ?? '0';
      const limit = url.searchParams.get('limit') ?? '100';
      if (!WHOLE.test(after) || !/^[1-9][0-9]{0,2}$/.test(limit)) throw new SimRefusal(400, 'SCHEMA', 'after is a whole number, limit 1 to 999');
      return deliver(res, feed.page(BigInt(after), Number(limit)));
    }
    if (method === 'GET' && path === `${base}/heartbeat`) {
      if (!feed.heartbeatOk()) throw new SimRefusal(503, 'NO_HEARTBEAT', `the ${feed.system} heartbeat has stopped`);
      return send(res, 200, { head: feed.head().toString() });
    }
    if (method === 'GET' && path === `${base}/reconciliation`) {
      const from = url.searchParams.get('from') ?? '';
      const to = url.searchParams.get('to') ?? '';
      if (!WHOLE.test(from) || !WHOLE.test(to) || BigInt(from) >= BigInt(to)) throw new SimRefusal(400, 'SCHEMA', 'from and to are epoch microseconds, from < to');
      return send(res, 200, feed.reconciliation(BigInt(from), BigInt(to)));
    }
    const body = method === 'POST' || method === 'PUT' ? await readJson(req) : undefined;
    const r = plugin.route(method, path, url.searchParams, body);
    if (!r) throw new SimRefusal(404, 'NOT_FOUND', `${method} ${path} is not a route of this simulator`);
    if (r.read && r.status === 200) return deliver(res, r.body);
    return send(res, r.status, r.body);
  }

  const server: Server = createServer((req, res) => {
    void handle(req, res).catch((error: unknown) => {
      if (res.headersSent) return;
      if (error instanceof SimRefusal) return send(res, error.status, { error: { code: error.code, message: error.message.slice(0, 500) } });
      send(res, 500, { error: { code: 'INTERNAL', message: error instanceof Error ? error.message : String(error) } });
    });
  });
  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(http.port, http.host, () => resolve());
  });
  const a = server.address();
  return {
    feed,
    port: a && typeof a === 'object' ? a.port : http.port,
    async close() {
      server.closeAllConnections();
      await new Promise<void>((r) => server.close(() => r()));
    },
  };
}

/** host:port from an environment variable (a loopback default), for the simulators' main files. */
export function listenAddress(value: string | undefined, fallback: string): { host: string; port: number } {
  const text = value && value !== '' ? value : fallback;
  const m = /^(.+):(\d+)$/.exec(text);
  if (!m) throw new Error(`not a host:port address: ${text}`);
  return { host: m[1] ?? '127.0.0.1', port: Number(m[2]) };
}

